BEGIN;
DO $$
DECLARE
  v_subject_id UUID;
  v_topic_id UUID;
  v_test_id BIGINT;
BEGIN
  SELECT id INTO v_subject_id FROM test_subjects WHERE name ILIKE '%cardio%' ORDER BY id LIMIT 1;
  IF v_subject_id IS NULL THEN
    INSERT INTO test_subjects (name, description) VALUES ('Cardiovascular System', 'Cardiovascular notes') RETURNING id INTO v_subject_id;
  END IF;
  SELECT id INTO v_topic_id FROM test_topics WHERE name = 'CABG & PCI' ORDER BY (SELECT COUNT(*) FROM test_questions q WHERE q.topic_id = test_topics.id) DESC, created_at ASC LIMIT 1;
  IF v_topic_id IS NULL THEN
    INSERT INTO test_topics (subject_id, name, description, status) VALUES (v_subject_id, 'CABG & PCI', 'Revascularization indications and post-op priorities', 'published') RETURNING id INTO v_topic_id;
  END IF;
  SELECT id INTO v_test_id FROM tests WHERE is_active = true ORDER BY id LIMIT 1;
  IF v_test_id IS NULL THEN
    INSERT INTO tests (test_name, system_category, description, is_active)
    VALUES ('Cardiovascular System - CABG and PCI (Generated)', 'Cardiovascular System', 'Auto-generated NCLEX question set', true)
    RETURNING id INTO v_test_id;
  END IF;
  DELETE FROM test_questions WHERE topic_id = v_topic_id AND category = 'CABG and PCI - NCLEX';
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the CABG & PCI note, which statement about "CAD progression" is most accurate?', 'According to the CABG & PCI note, which statement about "CAD progression" is most accurate?', '[{"id": "a", "text": "CAD progression ends at stable angina."}, {"id": "b", "text": "Post-procedure education has minimal impact on outcomes."}, {"id": "c", "text": "DES removes need for any antiplatelet therapy."}, {"id": "d", "text": "Progression reflects worsening myocardial perfusion."}]'::jsonb, '["d"]'::jsonb, 'Correct because CAD progression listed is stable angina to unstable angina to NSTEMI to STEMI. Escalating symptoms should trigger faster revascularization decisions.', 'CABG and PCI - NCLEX', false, 1, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Revascularization options" in CABG & PCI. Which statement is correct?', 'The nurse is reviewing "Revascularization options" in CABG & PCI. Which statement is correct?', '[{"id": "a", "text": "Post-procedure education has minimal impact on outcomes."}, {"id": "b", "text": "PCI and CABG are interchangeable regardless anatomy."}, {"id": "c", "text": "Selection factors include vessels/anatomy/EF/comorbidities."}, {"id": "d", "text": "Left main multivessel disease is always first-choice PCI."}]'::jsonb, '["c"]'::jsonb, 'Correct because Two options are PCI (less invasive) and CABG (surgery), selected by vessel count, anatomy, EF, and comorbidities. Procedure choice must match anatomy and risk profile, not convenience.', 'CABG and PCI - NCLEX', false, 2, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "PCI basics" in CABG & PCI?', 'Which clinical judgment is most accurate regarding "PCI basics" in CABG & PCI?', '[{"id": "a", "text": "Restenosis is impossible with stents."}, {"id": "b", "text": "PCI is open-heart surgery."}, {"id": "c", "text": "Stent scaffold may be left in artery."}, {"id": "d", "text": "PCI is contraindicated in all acute MI."}]'::jsonb, '["c"]'::jsonb, 'Correct because PCI is catheter-based via radial or femoral access, using balloon angioplasty and often stent placement. Monitor access-site and reperfusion outcomes immediately post-procedure.', 'CABG and PCI - NCLEX', false, 3, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Drug-eluting stent role" in CABG & PCI?', 'In rapid prioritization, which statement is most consistent with "Drug-eluting stent role" in CABG & PCI?', '[{"id": "a", "text": "Vitals can be deferred for several hours."}, {"id": "b", "text": "Stent choice affects post-procedure management."}, {"id": "c", "text": "Renal function check is unnecessary pre-PCI."}, {"id": "d", "text": "DES removes need for any antiplatelet therapy."}]'::jsonb, '["b"]'::jsonb, 'Correct because Drug-eluting stents contain antiproliferative medication to reduce restenosis. Maintain antiplatelet adherence to prevent stent thrombosis/restenosis.', 'CABG and PCI - NCLEX', false, 4, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Primary PCI timing" in CABG & PCI would the nurse recognize as correct?', 'Which conclusion about "Primary PCI timing" in CABG & PCI would the nurse recognize as correct?', '[{"id": "a", "text": "Site checks are unnecessary after sheath removal."}, {"id": "b", "text": "Internal mammary graft is never connected to LAD."}, {"id": "c", "text": "Time-to-balloon directly impacts myocardial salvage."}, {"id": "d", "text": "Primary PCI is not used for STEMI."}]'::jsonb, '["c"]'::jsonb, 'Correct because Primary PCI is treatment of choice for STEMI with door-to-balloon goal within 90 minutes. Time-to-balloon directly impacts myocardial salvage.', 'CABG and PCI - NCLEX', false, 5, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the CABG & PCI note, which statement about "PCI indications" is most accurate?', 'According to the CABG & PCI note, which statement about "PCI indications" is most accurate?', '[{"id": "a", "text": "Left main multivessel disease is always first-choice PCI."}, {"id": "b", "text": "Post-procedure education has minimal impact on outcomes."}, {"id": "c", "text": "Use PCI when anatomy and risk profile make catheter strategy appropriate."}, {"id": "d", "text": "Frequent reassessment can be delayed when initial vitals are stable."}]'::jsonb, '["c"]'::jsonb, 'Correct because PCI indications include STEMI/NSTEMI, refractory unstable angina, suitable 1–2 vessel disease, or high CABG surgical risk. Use PCI when anatomy and risk profile make catheter strategy appropriate.', 'CABG and PCI - NCLEX', false, 6, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Pre-PCI preparation" in CABG & PCI. Which statement is correct?', 'The nurse is reviewing "Pre-PCI preparation" in CABG & PCI. Which statement is correct?', '[{"id": "a", "text": "Renal function check is unnecessary pre-PCI."}, {"id": "b", "text": "Pedal pulses are assessed/marked pre-procedure."}, {"id": "c", "text": "CABG is contraindicated after failed PCI."}, {"id": "d", "text": "Diabetic multivessel CAD always avoids surgery."}]'::jsonb, '["b"]'::jsonb, 'Correct because Pre-PCI care includes NPO 4–6 hours, IV access, type and screen, DAPT initiation, anticoagulation, creatinine check, and pulse marking. Optimize safety by preparing bleeding, renal, and access monitoring plans.', 'CABG and PCI - NCLEX', false, 7, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Post-PCI vitals and site care" in CABG & PCI?', 'Which clinical judgment is most accurate regarding "Post-PCI vitals and site care" in CABG & PCI?', '[{"id": "a", "text": "Bleeding/hematoma monitoring is required."}, {"id": "b", "text": "Restenosis is impossible with stents."}, {"id": "c", "text": "Pulmonary exercises are avoided after CABG."}, {"id": "d", "text": "Vitals can be deferred for several hours."}]'::jsonb, '["a"]'::jsonb, 'Correct because Post-PCI protocol includes frequent vitals and puncture site checks for bleeding/hematoma. Early detection of access complications prevents deterioration.', 'CABG and PCI - NCLEX', false, 8, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Post-PCI limb and hydration" in CABG & PCI?', 'In rapid prioritization, which statement is most consistent with "Post-PCI limb and hydration" in CABG & PCI?', '[{"id": "a", "text": "Chest tube output trends are unimportant."}, {"id": "b", "text": "500 mL/hr output is expected and ignored."}, {"id": "c", "text": "Immediate vigorous leg flexion is recommended."}, {"id": "d", "text": "Hydration is encouraged to flush contrast."}]'::jsonb, '["d"]'::jsonb, 'Correct because Femoral approach requires limb straight with bedrest 4–6 hours; fluids are encouraged to clear contrast. Protect access integrity while lowering nephropathy risk.', 'CABG and PCI - NCLEX', false, 9, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Post-PCI medication adherence" in CABG & PCI would the nurse recognize as correct?', 'Which conclusion about "Post-PCI medication adherence" in CABG & PCI would the nurse recognize as correct?', '[{"id": "a", "text": "Nonadherence significantly raises stent thrombosis risk."}, {"id": "b", "text": "Internal mammary graft is never connected to LAD."}, {"id": "c", "text": "Post-procedure education has minimal impact on outcomes."}, {"id": "d", "text": "Aspirin alone is immediate replacement for all stent patients."}]'::jsonb, '["a"]'::jsonb, 'Correct because Dual antiplatelet therapy is required for at least 1 year after stent placement. Nonadherence significantly raises stent thrombosis risk.', 'CABG and PCI - NCLEX', false, 10, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the CABG & PCI note, which statement about "PCI complications" is most accurate?', 'According to the CABG & PCI note, which statement about "PCI complications" is most accurate?', '[{"id": "a", "text": "V-fib is listed most common post-CABG rhythm."}, {"id": "b", "text": "CABG is contraindicated after failed PCI."}, {"id": "c", "text": "Stent thrombosis is emergency complication."}, {"id": "d", "text": "Restenosis is impossible with stents."}]'::jsonb, '["c"]'::jsonb, 'Correct because Listed PCI complications include access-site bleeding (most common), contrast nephropathy, arterial dissection, restenosis/re-occlusion, and stent thrombosis. Monitor for ischemic recurrence and bleeding/renal complications continuously.', 'CABG and PCI - NCLEX', false, 11, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "CABG definition" in CABG & PCI. Which statement is correct?', 'The nurse is reviewing "CABG definition" in CABG & PCI. Which statement is correct?', '[{"id": "a", "text": "CABG is contraindicated after failed PCI."}, {"id": "b", "text": "CABG is a bedside catheter procedure."}, {"id": "c", "text": "Pulmonary exercises are avoided after CABG."}, {"id": "d", "text": "Bypass grafts reroute flow around blockage."}]'::jsonb, '["d"]'::jsonb, 'Correct because CABG is open-heart bypass surgery using grafts to route blood around blocked coronaries. Post-op priorities focus on airway, hemodynamics, and graft-related complications.', 'CABG and PCI - NCLEX', false, 12, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "CABG graft options" in CABG & PCI?', 'Which clinical judgment is most accurate regarding "CABG graft options" in CABG & PCI?', '[{"id": "a", "text": "Frequent reassessment can be delayed when initial vitals are stable."}, {"id": "b", "text": "Post-procedure education has minimal impact on outcomes."}, {"id": "c", "text": "Understand graft source/patency differences for long-term follow-up education."}, {"id": "d", "text": "Internal mammary graft is never connected to LAD."}]'::jsonb, '["c"]'::jsonb, 'Correct because Graft choices include reversed saphenous vein, internal mammary artery (most durable to LAD), and radial artery. Understand graft source/patency differences for long-term follow-up education.', 'CABG and PCI - NCLEX', false, 13, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "CABG indications high risk anatomy" in CABG & PCI?', 'In rapid prioritization, which statement is most consistent with "CABG indications high risk anatomy" in CABG & PCI?', '[{"id": "a", "text": "Escalate to surgical strategy for high-risk multivessel anatomy."}, {"id": "b", "text": "Left main stenosis is managed only with lifestyle."}, {"id": "c", "text": "Frequent reassessment can be delayed when initial vitals are stable."}, {"id": "d", "text": "Post-procedure education has minimal impact on outcomes."}]'::jsonb, '["a"]'::jsonb, 'Correct because CABG indications include left main disease >50%, 3-vessel CAD especially with reduced EF, and proximal LAD involvement. Escalate to surgical strategy for high-risk multivessel anatomy.', 'CABG and PCI - NCLEX', false, 14, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Other CABG indications" in CABG & PCI would the nurse recognize as correct?', 'Which conclusion about "Other CABG indications" in CABG & PCI would the nurse recognize as correct?', '[{"id": "a", "text": "Redness and fever are expected, no report needed."}, {"id": "b", "text": "Diabetic multivessel CAD always avoids surgery."}, {"id": "c", "text": "Tube removal is based only on patient request."}, {"id": "d", "text": "CABG can be chosen when PCI strategy insufficient."}]'::jsonb, '["d"]'::jsonb, 'Correct because CABG is indicated for failed PCI and in diabetic patients with multivessel CAD. Recognize scenarios where surgery outperforms repeat catheter interventions.', 'CABG and PCI - NCLEX', false, 15, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the CABG & PCI note, which statement about "Post-CABG airway care" is most accurate?', 'According to the CABG & PCI note, which statement about "Post-CABG airway care" is most accurate?', '[{"id": "a", "text": "Post-procedure education has minimal impact on outcomes."}, {"id": "b", "text": "Pulmonary exercises are avoided after CABG."}, {"id": "c", "text": "Respiratory optimization reduces post-op pulmonary complications."}, {"id": "d", "text": "Frequent reassessment can be delayed when initial vitals are stable."}]'::jsonb, '["c"]'::jsonb, 'Correct because Post-op patient is initially intubated, extubated when stable; monitor ABGs and use incentive spirometry/deep breathing to prevent atelectasis. Respiratory optimization reduces post-op pulmonary complications.', 'CABG and PCI - NCLEX', false, 16, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Chest tube threshold" in CABG & PCI. Which statement is correct?', 'The nurse is reviewing "Chest tube threshold" in CABG & PCI. Which statement is correct?', '[{"id": "a", "text": "500 mL/hr output is expected and ignored."}, {"id": "b", "text": "High output indicates possible hemorrhage."}, {"id": "c", "text": "Chest tube output trends are unimportant."}, {"id": "d", "text": "Medication adherence is optional after stent."}]'::jsonb, '["b"]'::jsonb, 'Correct because Chest tube output greater than 100 mL/hr for 2+ hours suggests hemorrhage and requires provider notification. Treat persistent high drainage as possible active bleeding emergency.', 'CABG and PCI - NCLEX', false, 17, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Chest tube handling" in CABG & PCI?', 'Which clinical judgment is most accurate regarding "Chest tube handling" in CABG & PCI?', '[{"id": "a", "text": "Post-procedure education has minimal impact on outcomes."}, {"id": "b", "text": "Frequent reassessment can be delayed when initial vitals are stable."}, {"id": "c", "text": "Tube removal is based only on patient request."}, {"id": "d", "text": "Maintain drainage patency and monitor for removal readiness safely."}]'::jsonb, '["d"]'::jsonb, 'Correct because Chest tubes should remain dependent without kinks and may be removed when output drops below 25–50 mL per shift. Maintain drainage patency and monitor for removal readiness safely.', 'CABG and PCI - NCLEX', false, 18, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Post-CABG arrhythmia" in CABG & PCI?', 'In rapid prioritization, which statement is most consistent with "Post-CABG arrhythmia" in CABG & PCI?', '[{"id": "a", "text": "V-fib is listed most common post-CABG rhythm."}, {"id": "b", "text": "Redness and fever are expected, no report needed."}, {"id": "c", "text": "Heighten rhythm surveillance during peak AF window."}, {"id": "d", "text": "PCI and CABG are interchangeable regardless anatomy."}]'::jsonb, '["c"]'::jsonb, 'Correct because Atrial fibrillation is the most common arrhythmia after CABG, typically on post-op days 2–4. Heighten rhythm surveillance during peak AF window.', 'CABG and PCI - NCLEX', false, 19, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Tamponade vigilance" in CABG & PCI would the nurse recognize as correct?', 'Which conclusion about "Tamponade vigilance" in CABG & PCI would the nurse recognize as correct?', '[{"id": "a", "text": "Hemodynamic deterioration can indicate tamponade."}, {"id": "b", "text": "CABG is first choice for all simple 1-vessel lesions."}, {"id": "c", "text": "Redness and fever are expected, no report needed."}, {"id": "d", "text": "Tamponade risk is absent after CABG."}]'::jsonb, '["a"]'::jsonb, 'Correct because Post-CABG priorities include monitoring for tamponade using Beck''s triad and maintaining MAP at least 65. Low-pressure triad signs require immediate escalation after cardiac surgery.', 'CABG and PCI - NCLEX', false, 20, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the CABG & PCI note, which statement about "Sternal precautions lifting" is most accurate?', 'According to the CABG & PCI note, which statement about "Sternal precautions lifting" is most accurate?', '[{"id": "a", "text": "Protect sternal healing and prevent dehiscence."}, {"id": "b", "text": "No lifting restrictions exist post-CABG."}, {"id": "c", "text": "DES removes need for any antiplatelet therapy."}, {"id": "d", "text": "Medication adherence is optional after stent."}]'::jsonb, '["a"]'::jsonb, 'Correct because Sternal precautions include no lifting over 5–10 pounds for 6–8 weeks. Protect sternal healing and prevent dehiscence.', 'CABG and PCI - NCLEX', false, 21, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Other sternal precautions" in CABG & PCI. Which statement is correct?', 'The nurse is reviewing "Other sternal precautions" in CABG & PCI. Which statement is correct?', '[{"id": "a", "text": "Teach movement restrictions clearly before discharge."}, {"id": "b", "text": "Tamponade surveillance is not needed after CABG."}, {"id": "c", "text": "Post-procedure education has minimal impact on outcomes."}, {"id": "d", "text": "Unrestricted driving starts day after surgery."}]'::jsonb, '["a"]'::jsonb, 'Correct because No heavy pushing/pulling, no driving 4–6 weeks, and splint sternum with pillow when coughing/sneezing. Teach movement restrictions clearly before discharge.', 'CABG and PCI - NCLEX', false, 22, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Sternal wound red flags" in CABG & PCI?', 'Which clinical judgment is most accurate regarding "Sternal wound red flags" in CABG & PCI?', '[{"id": "a", "text": "Prompt reporting is part of discharge teaching."}, {"id": "b", "text": "Sternal clicking indicates normal healing."}, {"id": "c", "text": "PCI and CABG are interchangeable regardless anatomy."}, {"id": "d", "text": "Redness and fever are expected, no report needed."}]'::jsonb, '["a"]'::jsonb, 'Correct because Patients should report sternal clicking, drainage, fever, or increasing redness. Early infection/dehiscence signs require prompt evaluation.', 'CABG and PCI - NCLEX', false, 23, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "PCI vs CABG outcomes summary" in CABG & PCI?', 'In rapid prioritization, which statement is most consistent with "PCI vs CABG outcomes summary" in CABG & PCI?', '[{"id": "a", "text": "CABG is first choice for all simple 1-vessel lesions."}, {"id": "b", "text": "PCI and CABG are interchangeable regardless anatomy."}, {"id": "c", "text": "Procedure selection differs by disease complexity."}, {"id": "d", "text": "Post-procedure education has minimal impact on outcomes."}]'::jsonb, '["c"]'::jsonb, 'Correct because PCI has shorter recovery and suits selected 1–2 vessel/STEMI/high-surgical-risk cases; CABG has longer recovery and suits left main/multivessel/DM/low EF. Balance invasiveness and durability against anatomy and comorbidity burden.', 'CABG and PCI - NCLEX', false, 24, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "NCLEX priority synthesis" in CABG & PCI would the nurse recognize as correct?', 'Which conclusion about "NCLEX priority synthesis" in CABG & PCI would the nurse recognize as correct?', '[{"id": "a", "text": "Post-procedure education has minimal impact on outcomes."}, {"id": "b", "text": "Focus teaching and monitoring on highest-risk preventable complications."}, {"id": "c", "text": "Tamponade surveillance is not needed after CABG."}, {"id": "d", "text": "Frequent reassessment can be delayed when initial vitals are stable."}]'::jsonb, '["b"]'::jsonb, 'Correct because NCLEX priorities emphasize post-CABG tamponade assessment, strict sternal precautions, and post-PCI DAPT compliance. Focus teaching and monitoring on highest-risk preventable complications.', 'CABG and PCI - NCLEX', false, 25, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the CABG & PCI note, which statement about "CAD progression" is most accurate?', 'According to the CABG & PCI note, which statement about "CAD progression" is most accurate?', '[{"id": "a", "text": "Stable angina appears before unstable in progression."}, {"id": "b", "text": "Post-procedure education has minimal impact on outcomes."}, {"id": "c", "text": "Fluid restriction is mandatory after contrast."}, {"id": "d", "text": "CAD progression ends at stable angina."}]'::jsonb, '["a"]'::jsonb, 'Correct because CAD progression listed is stable angina to unstable angina to NSTEMI to STEMI. Escalating symptoms should trigger faster revascularization decisions.', 'CABG and PCI - NCLEX', false, 26, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Revascularization options" in CABG & PCI. Which statement is correct?', 'The nurse is reviewing "Revascularization options" in CABG & PCI. Which statement is correct?', '[{"id": "a", "text": "PCI and CABG are interchangeable regardless anatomy."}, {"id": "b", "text": "Procedure choice must match anatomy and risk profile, not convenience."}, {"id": "c", "text": "Aspirin alone is immediate replacement for all stent patients."}, {"id": "d", "text": "Frequent reassessment can be delayed when initial vitals are stable."}]'::jsonb, '["b"]'::jsonb, 'Correct because Two options are PCI (less invasive) and CABG (surgery), selected by vessel count, anatomy, EF, and comorbidities. Procedure choice must match anatomy and risk profile, not convenience.', 'CABG and PCI - NCLEX', false, 27, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "PCI basics" in CABG & PCI?', 'Which clinical judgment is most accurate regarding "PCI basics" in CABG & PCI?', '[{"id": "a", "text": "Monitor access-site and reperfusion outcomes immediately post-procedure."}, {"id": "b", "text": "Frequent reassessment can be delayed when initial vitals are stable."}, {"id": "c", "text": "PCI is open-heart surgery."}, {"id": "d", "text": "Left main multivessel disease is always first-choice PCI."}]'::jsonb, '["a"]'::jsonb, 'Correct because PCI is catheter-based via radial or femoral access, using balloon angioplasty and often stent placement. Monitor access-site and reperfusion outcomes immediately post-procedure.', 'CABG and PCI - NCLEX', false, 28, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Drug-eluting stent role" in CABG & PCI?', 'In rapid prioritization, which statement is most consistent with "Drug-eluting stent role" in CABG & PCI?', '[{"id": "a", "text": "Maintain antiplatelet adherence to prevent stent thrombosis/restenosis."}, {"id": "b", "text": "Frequent reassessment can be delayed when initial vitals are stable."}, {"id": "c", "text": "Post-procedure education has minimal impact on outcomes."}, {"id": "d", "text": "DES removes need for any antiplatelet therapy."}]'::jsonb, '["a"]'::jsonb, 'Correct because Drug-eluting stents contain antiproliferative medication to reduce restenosis. Maintain antiplatelet adherence to prevent stent thrombosis/restenosis.', 'CABG and PCI - NCLEX', false, 29, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Primary PCI timing" in CABG & PCI would the nurse recognize as correct?', 'Which conclusion about "Primary PCI timing" in CABG & PCI would the nurse recognize as correct?', '[{"id": "a", "text": "Primary PCI is preferred STEMI reperfusion strategy."}, {"id": "b", "text": "Site checks are unnecessary after sheath removal."}, {"id": "c", "text": "Primary PCI is not used for STEMI."}, {"id": "d", "text": "Internal mammary graft is never connected to LAD."}]'::jsonb, '["a"]'::jsonb, 'Correct because Primary PCI is treatment of choice for STEMI with door-to-balloon goal within 90 minutes. Time-to-balloon directly impacts myocardial salvage.', 'CABG and PCI - NCLEX', false, 30, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the CABG & PCI note, which statement about "PCI indications" is most accurate?', 'According to the CABG & PCI note, which statement about "PCI indications" is most accurate?', '[{"id": "a", "text": "Aspirin alone is immediate replacement for all stent patients."}, {"id": "b", "text": "Frequent reassessment can be delayed when initial vitals are stable."}, {"id": "c", "text": "PCI indications include STEMI/NSTEMI, refractory unstable angina, suitable 1–2 vessel disease, or high CABG surgical risk."}, {"id": "d", "text": "Left main multivessel disease is always first-choice PCI."}]'::jsonb, '["c"]'::jsonb, 'Correct because PCI indications include STEMI/NSTEMI, refractory unstable angina, suitable 1–2 vessel disease, or high CABG surgical risk. Use PCI when anatomy and risk profile make catheter strategy appropriate.', 'CABG and PCI - NCLEX', false, 31, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Pre-PCI preparation" in CABG & PCI. Which statement is correct?', 'The nurse is reviewing "Pre-PCI preparation" in CABG & PCI. Which statement is correct?', '[{"id": "a", "text": "Renal function check is unnecessary pre-PCI."}, {"id": "b", "text": "Aspirin alone is immediate replacement for all stent patients."}, {"id": "c", "text": "Optimize safety by preparing bleeding, renal, and access monitoring plans."}, {"id": "d", "text": "Frequent reassessment can be delayed when initial vitals are stable."}]'::jsonb, '["c"]'::jsonb, 'Correct because Pre-PCI care includes NPO 4–6 hours, IV access, type and screen, DAPT initiation, anticoagulation, creatinine check, and pulse marking. Optimize safety by preparing bleeding, renal, and access monitoring plans.', 'CABG and PCI - NCLEX', false, 32, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Post-PCI vitals and site care" in CABG & PCI?', 'Which clinical judgment is most accurate regarding "Post-PCI vitals and site care" in CABG & PCI?', '[{"id": "a", "text": "Vitals can be deferred for several hours."}, {"id": "b", "text": "Access-site surveillance is key post-PCI."}, {"id": "c", "text": "Restenosis is impossible with stents."}, {"id": "d", "text": "Pulmonary exercises are avoided after CABG."}]'::jsonb, '["b"]'::jsonb, 'Correct because Post-PCI protocol includes frequent vitals and puncture site checks for bleeding/hematoma. Early detection of access complications prevents deterioration.', 'CABG and PCI - NCLEX', false, 33, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Post-PCI limb and hydration" in CABG & PCI?', 'In rapid prioritization, which statement is most consistent with "Post-PCI limb and hydration" in CABG & PCI?', '[{"id": "a", "text": "500 mL/hr output is expected and ignored."}, {"id": "b", "text": "Hydration is encouraged to flush contrast."}, {"id": "c", "text": "Immediate vigorous leg flexion is recommended."}, {"id": "d", "text": "Chest tube output trends are unimportant."}]'::jsonb, '["b"]'::jsonb, 'Correct because Femoral approach requires limb straight with bedrest 4–6 hours; fluids are encouraged to clear contrast. Protect access integrity while lowering nephropathy risk.', 'CABG and PCI - NCLEX', false, 34, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Post-PCI medication adherence" in CABG & PCI would the nurse recognize as correct?', 'Which conclusion about "Post-PCI medication adherence" in CABG & PCI would the nurse recognize as correct?', '[{"id": "a", "text": "Clamp chest tubes routinely to test patency."}, {"id": "b", "text": "Medication adherence is critical after stent."}, {"id": "c", "text": "Aspirin alone is immediate replacement for all stent patients."}, {"id": "d", "text": "Tube removal is based only on patient request."}]'::jsonb, '["b"]'::jsonb, 'Correct because Dual antiplatelet therapy is required for at least 1 year after stent placement. Nonadherence significantly raises stent thrombosis risk.', 'CABG and PCI - NCLEX', false, 35, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the CABG & PCI note, which statement about "PCI complications" is most accurate?', 'According to the CABG & PCI note, which statement about "PCI complications" is most accurate?', '[{"id": "a", "text": "Frequent reassessment can be delayed when initial vitals are stable."}, {"id": "b", "text": "Monitor for ischemic recurrence and bleeding/renal complications continuously."}, {"id": "c", "text": "Post-procedure education has minimal impact on outcomes."}, {"id": "d", "text": "Restenosis is impossible with stents."}]'::jsonb, '["b"]'::jsonb, 'Correct because Listed PCI complications include access-site bleeding (most common), contrast nephropathy, arterial dissection, restenosis/re-occlusion, and stent thrombosis. Monitor for ischemic recurrence and bleeding/renal complications continuously.', 'CABG and PCI - NCLEX', false, 36, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "CABG definition" in CABG & PCI. Which statement is correct?', 'The nurse is reviewing "CABG definition" in CABG & PCI. Which statement is correct?', '[{"id": "a", "text": "CABG is a bedside catheter procedure."}, {"id": "b", "text": "CABG is contraindicated after failed PCI."}, {"id": "c", "text": "Diabetic multivessel CAD always avoids surgery."}, {"id": "d", "text": "Bypass grafts reroute flow around blockage."}]'::jsonb, '["d"]'::jsonb, 'Correct because CABG is open-heart bypass surgery using grafts to route blood around blocked coronaries. Post-op priorities focus on airway, hemodynamics, and graft-related complications.', 'CABG and PCI - NCLEX', false, 37, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "CABG graft options" in CABG & PCI?', 'Which clinical judgment is most accurate regarding "CABG graft options" in CABG & PCI?', '[{"id": "a", "text": "Graft choices include reversed saphenous vein, internal mammary artery (most durable to LAD), and radial artery."}, {"id": "b", "text": "Internal mammary graft is never connected to LAD."}, {"id": "c", "text": "Post-procedure education has minimal impact on outcomes."}, {"id": "d", "text": "Frequent reassessment can be delayed when initial vitals are stable."}]'::jsonb, '["a"]'::jsonb, 'Correct because Graft choices include reversed saphenous vein, internal mammary artery (most durable to LAD), and radial artery. Understand graft source/patency differences for long-term follow-up education.', 'CABG and PCI - NCLEX', false, 38, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "CABG indications high risk anatomy" in CABG & PCI?', 'In rapid prioritization, which statement is most consistent with "CABG indications high risk anatomy" in CABG & PCI?', '[{"id": "a", "text": "CABG indications include left main disease >50%, 3-vessel CAD especially with reduced EF, and proximal LAD involvement."}, {"id": "b", "text": "Frequent reassessment can be delayed when initial vitals are stable."}, {"id": "c", "text": "Left main stenosis is managed only with lifestyle."}, {"id": "d", "text": "Post-procedure education has minimal impact on outcomes."}]'::jsonb, '["a"]'::jsonb, 'Correct because CABG indications include left main disease >50%, 3-vessel CAD especially with reduced EF, and proximal LAD involvement. Escalate to surgical strategy for high-risk multivessel anatomy.', 'CABG and PCI - NCLEX', false, 39, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Other CABG indications" in CABG & PCI would the nurse recognize as correct?', 'Which conclusion about "Other CABG indications" in CABG & PCI would the nurse recognize as correct?', '[{"id": "a", "text": "Post-procedure education has minimal impact on outcomes."}, {"id": "b", "text": "Frequent reassessment can be delayed when initial vitals are stable."}, {"id": "c", "text": "Diabetic multivessel CAD always avoids surgery."}, {"id": "d", "text": "Recognize scenarios where surgery outperforms repeat catheter interventions."}]'::jsonb, '["d"]'::jsonb, 'Correct because CABG is indicated for failed PCI and in diabetic patients with multivessel CAD. Recognize scenarios where surgery outperforms repeat catheter interventions.', 'CABG and PCI - NCLEX', false, 40, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the CABG & PCI note, which statement about "Post-CABG airway care" is most accurate?', 'According to the CABG & PCI note, which statement about "Post-CABG airway care" is most accurate?', '[{"id": "a", "text": "Frequent reassessment can be delayed when initial vitals are stable."}, {"id": "b", "text": "Post-op patient is initially intubated, extubated when stable; monitor ABGs and use incentive spirometry/deep breathing to prevent atelectasis."}, {"id": "c", "text": "Pulmonary exercises are avoided after CABG."}, {"id": "d", "text": "Post-procedure education has minimal impact on outcomes."}]'::jsonb, '["b"]'::jsonb, 'Correct because Post-op patient is initially intubated, extubated when stable; monitor ABGs and use incentive spirometry/deep breathing to prevent atelectasis. Respiratory optimization reduces post-op pulmonary complications.', 'CABG and PCI - NCLEX', false, 41, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Chest tube threshold" in CABG & PCI. Which statement is correct?', 'The nurse is reviewing "Chest tube threshold" in CABG & PCI. Which statement is correct?', '[{"id": "a", "text": "Tamponade risk is absent after CABG."}, {"id": "b", "text": "500 mL/hr output is expected and ignored."}, {"id": "c", "text": "Escalation/notification is required."}, {"id": "d", "text": "MAP target under 40 is acceptable."}]'::jsonb, '["c"]'::jsonb, 'Correct because Chest tube output greater than 100 mL/hr for 2+ hours suggests hemorrhage and requires provider notification. Treat persistent high drainage as possible active bleeding emergency.', 'CABG and PCI - NCLEX', false, 42, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Chest tube handling" in CABG & PCI?', 'Which clinical judgment is most accurate regarding "Chest tube handling" in CABG & PCI?', '[{"id": "a", "text": "Post-procedure education has minimal impact on outcomes."}, {"id": "b", "text": "Chest tubes should remain dependent without kinks and may be removed when output drops below 25–50 mL per shift."}, {"id": "c", "text": "Frequent reassessment can be delayed when initial vitals are stable."}, {"id": "d", "text": "Tube removal is based only on patient request."}]'::jsonb, '["b"]'::jsonb, 'Correct because Chest tubes should remain dependent without kinks and may be removed when output drops below 25–50 mL per shift. Maintain drainage patency and monitor for removal readiness safely.', 'CABG and PCI - NCLEX', false, 43, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Post-CABG arrhythmia" in CABG & PCI?', 'In rapid prioritization, which statement is most consistent with "Post-CABG arrhythmia" in CABG & PCI?', '[{"id": "a", "text": "Arrhythmias occur only immediately in OR."}, {"id": "b", "text": "Sternal clicking indicates normal healing."}, {"id": "c", "text": "Coughing should avoid splint support."}, {"id": "d", "text": "AF is most common post-CABG arrhythmia."}]'::jsonb, '["d"]'::jsonb, 'Correct because Atrial fibrillation is the most common arrhythmia after CABG, typically on post-op days 2–4. Heighten rhythm surveillance during peak AF window.', 'CABG and PCI - NCLEX', false, 44, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Tamponade vigilance" in CABG & PCI would the nurse recognize as correct?', 'Which conclusion about "Tamponade vigilance" in CABG & PCI would the nurse recognize as correct?', '[{"id": "a", "text": "Tamponade risk is absent after CABG."}, {"id": "b", "text": "Post-procedure education has minimal impact on outcomes."}, {"id": "c", "text": "Low-pressure triad signs require immediate escalation after cardiac surgery."}, {"id": "d", "text": "Frequent reassessment can be delayed when initial vitals are stable."}]'::jsonb, '["c"]'::jsonb, 'Correct because Post-CABG priorities include monitoring for tamponade using Beck''s triad and maintaining MAP at least 65. Low-pressure triad signs require immediate escalation after cardiac surgery.', 'CABG and PCI - NCLEX', false, 45, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the CABG & PCI note, which statement about "Sternal precautions lifting" is most accurate?', 'According to the CABG & PCI note, which statement about "Sternal precautions lifting" is most accurate?', '[{"id": "a", "text": "Heavy lifting accelerates healing."}, {"id": "b", "text": "DES increases restenosis intentionally."}, {"id": "c", "text": "No lifting restrictions exist post-CABG."}, {"id": "d", "text": "Precaution supports sternal healing."}]'::jsonb, '["d"]'::jsonb, 'Correct because Sternal precautions include no lifting over 5–10 pounds for 6–8 weeks. Protect sternal healing and prevent dehiscence.', 'CABG and PCI - NCLEX', false, 46, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Other sternal precautions" in CABG & PCI. Which statement is correct?', 'The nurse is reviewing "Other sternal precautions" in CABG & PCI. Which statement is correct?', '[{"id": "a", "text": "Post-procedure education has minimal impact on outcomes."}, {"id": "b", "text": "No heavy pushing/pulling, no driving 4–6 weeks, and splint sternum with pillow when coughing/sneezing."}, {"id": "c", "text": "Unrestricted driving starts day after surgery."}, {"id": "d", "text": "Frequent reassessment can be delayed when initial vitals are stable."}]'::jsonb, '["b"]'::jsonb, 'Correct because No heavy pushing/pulling, no driving 4–6 weeks, and splint sternum with pillow when coughing/sneezing. Teach movement restrictions clearly before discharge.', 'CABG and PCI - NCLEX', false, 47, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Sternal wound red flags" in CABG & PCI?', 'Which clinical judgment is most accurate regarding "Sternal wound red flags" in CABG & PCI?', '[{"id": "a", "text": "PCI is contraindicated in all acute MI."}, {"id": "b", "text": "CAD progression ends at stable angina."}, {"id": "c", "text": "Drainage/fever/redness are warning signs."}, {"id": "d", "text": "Sternal clicking indicates normal healing."}]'::jsonb, '["c"]'::jsonb, 'Correct because Patients should report sternal clicking, drainage, fever, or increasing redness. Early infection/dehiscence signs require prompt evaluation.', 'CABG and PCI - NCLEX', false, 48, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "PCI vs CABG outcomes summary" in CABG & PCI?', 'In rapid prioritization, which statement is most consistent with "PCI vs CABG outcomes summary" in CABG & PCI?', '[{"id": "a", "text": "Post-procedure education has minimal impact on outcomes."}, {"id": "b", "text": "CABG is first choice for all simple 1-vessel lesions."}, {"id": "c", "text": "PCI and CABG are interchangeable regardless anatomy."}, {"id": "d", "text": "CABG preferred for left main/3-vessel/DM/low EF patterns."}]'::jsonb, '["d"]'::jsonb, 'Correct because PCI has shorter recovery and suits selected 1–2 vessel/STEMI/high-surgical-risk cases; CABG has longer recovery and suits left main/multivessel/DM/low EF. Balance invasiveness and durability against anatomy and comorbidity burden.', 'CABG and PCI - NCLEX', false, 49, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "NCLEX priority synthesis" in CABG & PCI would the nurse recognize as correct?', 'Which conclusion about "NCLEX priority synthesis" in CABG & PCI would the nurse recognize as correct?', '[{"id": "a", "text": "Post-procedure education has minimal impact on outcomes."}, {"id": "b", "text": "Frequent reassessment can be delayed when initial vitals are stable."}, {"id": "c", "text": "Tamponade surveillance is not needed after CABG."}, {"id": "d", "text": "NCLEX priorities emphasize post-CABG tamponade assessment, strict sternal precautions, and post-PCI DAPT compliance."}]'::jsonb, '["d"]'::jsonb, 'Correct because NCLEX priorities emphasize post-CABG tamponade assessment, strict sternal precautions, and post-PCI DAPT compliance. Focus teaching and monitoring on highest-risk preventable complications.', 'CABG and PCI - NCLEX', false, 50, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "CAD progression" in CABG & PCI are correct? (Select all that apply)', 'Which statements about "CAD progression" in CABG & PCI are correct? (Select all that apply)', '[{"id": "a", "text": "NSTEMI and STEMI are later stages."}, {"id": "b", "text": "Progression reflects worsening myocardial perfusion."}, {"id": "c", "text": "STEMI is earliest stage."}, {"id": "d", "text": "Stable angina appears before unstable in progression."}, {"id": "e", "text": "CAD progression ends at stable angina."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: CAD progression listed is stable angina to unstable angina to NSTEMI to STEMI.', 'CABG and PCI - NCLEX', true, 51, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For CABG & PCI, which findings or actions relate to "Revascularization options"? (Select all that apply)', 'For CABG & PCI, which findings or actions relate to "Revascularization options"? (Select all that apply)', '[{"id": "a", "text": "CABG is surgical option."}, {"id": "b", "text": "PCI and CABG are interchangeable regardless anatomy."}, {"id": "c", "text": "Selection factors include vessels/anatomy/EF/comorbidities."}, {"id": "d", "text": "PCI is less invasive option."}, {"id": "e", "text": "EF is irrelevant to decision."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Two options are PCI (less invasive) and CABG (surgery), selected by vessel count, anatomy, EF, and comorbidities.', 'CABG and PCI - NCLEX', true, 52, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "PCI basics" in CABG & PCI? (Select all that apply)', 'The nurse is planning care. Which items apply to "PCI basics" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "Balloon compresses plaque."}, {"id": "b", "text": "PCI never uses stents."}, {"id": "c", "text": "PCI is open-heart surgery."}, {"id": "d", "text": "Radial and femoral access are listed."}, {"id": "e", "text": "Stent scaffold may be left in artery."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: PCI is catheter-based via radial or femoral access, using balloon angioplasty and often stent placement.', 'CABG and PCI - NCLEX', true, 53, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Drug-eluting stent role" in CABG & PCI? (Select all that apply)', 'Which of the following are consistent with "Drug-eluting stent role" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "DES has antiproliferative coating."}, {"id": "b", "text": "DES aims to lower restenosis risk."}, {"id": "c", "text": "DES increases restenosis intentionally."}, {"id": "d", "text": "Stent choice affects post-procedure management."}, {"id": "e", "text": "DES removes need for any antiplatelet therapy."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Drug-eluting stents contain antiproliferative medication to reduce restenosis.', 'CABG and PCI - NCLEX', true, 54, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Primary PCI timing" in CABG & PCI? (Select all that apply)', 'During reassessment, which observations align with "Primary PCI timing" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "Primary PCI is preferred STEMI reperfusion strategy."}, {"id": "b", "text": "Primary PCI is not used for STEMI."}, {"id": "c", "text": "Primary PCI target is 24 hours."}, {"id": "d", "text": "STEMI door-to-balloon target is 90 min."}, {"id": "e", "text": "Rapid activation is essential."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Primary PCI is treatment of choice for STEMI with door-to-balloon goal within 90 minutes.', 'CABG and PCI - NCLEX', true, 55, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "PCI indications" in CABG & PCI are correct? (Select all that apply)', 'Which statements about "PCI indications" in CABG & PCI are correct? (Select all that apply)', '[{"id": "a", "text": "PCI is contraindicated in all acute MI."}, {"id": "b", "text": "STEMI and NSTEMI are listed indications."}, {"id": "c", "text": "Left main multivessel disease is always first-choice PCI."}, {"id": "d", "text": "Refractory unstable angina is listed indication."}, {"id": "e", "text": "1–2 vessel suitable anatomy is listed indication."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: PCI indications include STEMI/NSTEMI, refractory unstable angina, suitable 1–2 vessel disease, or high CABG surgical risk.', 'CABG and PCI - NCLEX', true, 56, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For CABG & PCI, which findings or actions relate to "Pre-PCI preparation"? (Select all that apply)', 'For CABG & PCI, which findings or actions relate to "Pre-PCI preparation"? (Select all that apply)', '[{"id": "a", "text": "Pulse baseline is not needed."}, {"id": "b", "text": "Creatinine check is listed for contrast risk."}, {"id": "c", "text": "NPO 4–6 hours is listed."}, {"id": "d", "text": "Pedal pulses are assessed/marked pre-procedure."}, {"id": "e", "text": "Renal function check is unnecessary pre-PCI."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Pre-PCI care includes NPO 4–6 hours, IV access, type and screen, DAPT initiation, anticoagulation, creatinine check, and pulse marking.', 'CABG and PCI - NCLEX', true, 57, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Post-PCI vitals and site care" in CABG & PCI? (Select all that apply)', 'The nurse is planning care. Which items apply to "Post-PCI vitals and site care" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "Site checks are unnecessary after sheath removal."}, {"id": "b", "text": "Access-site surveillance is key post-PCI."}, {"id": "c", "text": "Frequent scheduled vitals are listed."}, {"id": "d", "text": "Vitals can be deferred for several hours."}, {"id": "e", "text": "Bleeding/hematoma monitoring is required."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Post-PCI protocol includes frequent vitals and puncture site checks for bleeding/hematoma.', 'CABG and PCI - NCLEX', true, 58, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Post-PCI limb and hydration" in CABG & PCI? (Select all that apply)', 'Which of the following are consistent with "Post-PCI limb and hydration" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "Hydration is encouraged to flush contrast."}, {"id": "b", "text": "Immediate vigorous leg flexion is recommended."}, {"id": "c", "text": "Bedrest 4–6 hours listed for femoral access."}, {"id": "d", "text": "Fluid restriction is mandatory after contrast."}, {"id": "e", "text": "Affected femoral limb kept straight post-procedure."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Femoral approach requires limb straight with bedrest 4–6 hours; fluids are encouraged to clear contrast.', 'CABG and PCI - NCLEX', true, 59, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Post-PCI medication adherence" in CABG & PCI? (Select all that apply)', 'During reassessment, which observations align with "Post-PCI medication adherence" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "DAPT stops after 48 hours."}, {"id": "b", "text": "DAPT minimum one year is listed."}, {"id": "c", "text": "Medication adherence is critical after stent."}, {"id": "d", "text": "Aspirin alone is immediate replacement for all stent patients."}, {"id": "e", "text": "Aspirin + P2Y12 strategy is emphasized."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Dual antiplatelet therapy is required for at least 1 year after stent placement.', 'CABG and PCI - NCLEX', true, 60, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "PCI complications" in CABG & PCI are correct? (Select all that apply)', 'Which statements about "PCI complications" in CABG & PCI are correct? (Select all that apply)', '[{"id": "a", "text": "Stent thrombosis is emergency complication."}, {"id": "b", "text": "Contrast nephropathy is listed."}, {"id": "c", "text": "Bleeding at access site is most common complication listed."}, {"id": "d", "text": "Restenosis is impossible with stents."}, {"id": "e", "text": "PCI has no renal complications."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Listed PCI complications include access-site bleeding (most common), contrast nephropathy, arterial dissection, restenosis/re-occlusion, and stent thrombosis.', 'CABG and PCI - NCLEX', true, 61, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For CABG & PCI, which findings or actions relate to "CABG definition"? (Select all that apply)', 'For CABG & PCI, which findings or actions relate to "CABG definition"? (Select all that apply)', '[{"id": "a", "text": "CABG avoids any graft vessel use."}, {"id": "b", "text": "CABG is a bedside catheter procedure."}, {"id": "c", "text": "CABG is revascularization option for complex CAD."}, {"id": "d", "text": "Bypass grafts reroute flow around blockage."}, {"id": "e", "text": "CABG is open-heart surgery in note."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: CABG is open-heart bypass surgery using grafts to route blood around blocked coronaries.', 'CABG and PCI - NCLEX', true, 62, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "CABG graft options" in CABG & PCI? (Select all that apply)', 'The nurse is planning care. Which items apply to "CABG graft options" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "Radial artery can be used."}, {"id": "b", "text": "Internal mammary graft is never connected to LAD."}, {"id": "c", "text": "LIMA-to-LAD is highlighted as durable."}, {"id": "d", "text": "Only synthetic grafts are used."}, {"id": "e", "text": "Saphenous vein graft is listed."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Graft choices include reversed saphenous vein, internal mammary artery (most durable to LAD), and radial artery.', 'CABG and PCI - NCLEX', true, 63, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "CABG indications high risk anatomy" in CABG & PCI? (Select all that apply)', 'Which of the following are consistent with "CABG indications high risk anatomy" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "3-vessel with low EF favors CABG."}, {"id": "b", "text": "Single-vessel mild disease always requires CABG."}, {"id": "c", "text": "Left main >50% is listed indication."}, {"id": "d", "text": "Left main stenosis is managed only with lifestyle."}, {"id": "e", "text": "Proximal LAD involvement in 2-vessel disease listed indication."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: CABG indications include left main disease >50%, 3-vessel CAD especially with reduced EF, and proximal LAD involvement.', 'CABG and PCI - NCLEX', true, 64, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Other CABG indications" in CABG & PCI? (Select all that apply)', 'During reassessment, which observations align with "Other CABG indications" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "CABG is contraindicated after failed PCI."}, {"id": "b", "text": "Failed PCI is listed CABG indication."}, {"id": "c", "text": "Diabetes with multivessel CAD is listed indication."}, {"id": "d", "text": "CABG can be chosen when PCI strategy insufficient."}, {"id": "e", "text": "Diabetic multivessel CAD always avoids surgery."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: CABG is indicated for failed PCI and in diabetic patients with multivessel CAD.', 'CABG and PCI - NCLEX', true, 65, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Post-CABG airway care" in CABG & PCI are correct? (Select all that apply)', 'Which statements about "Post-CABG airway care" in CABG & PCI are correct? (Select all that apply)', '[{"id": "a", "text": "Pulmonary exercises are avoided after CABG."}, {"id": "b", "text": "ABG monitoring is listed."}, {"id": "c", "text": "Initial intubation then extubation when ready is listed."}, {"id": "d", "text": "ABGs are irrelevant post-CABG."}, {"id": "e", "text": "Incentive spirometry/deep breathing are listed."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Post-op patient is initially intubated, extubated when stable; monitor ABGs and use incentive spirometry/deep breathing to prevent atelectasis.', 'CABG and PCI - NCLEX', true, 66, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For CABG & PCI, which findings or actions relate to "Chest tube threshold"? (Select all that apply)', 'For CABG & PCI, which findings or actions relate to "Chest tube threshold"? (Select all that apply)', '[{"id": "a", "text": ">100 mL/hr for 2+ hr threshold is listed."}, {"id": "b", "text": "Chest tube output trends are unimportant."}, {"id": "c", "text": "Escalation/notification is required."}, {"id": "d", "text": "High output indicates possible hemorrhage."}, {"id": "e", "text": "500 mL/hr output is expected and ignored."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Chest tube output greater than 100 mL/hr for 2+ hours suggests hemorrhage and requires provider notification.', 'CABG and PCI - NCLEX', true, 67, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Chest tube handling" in CABG & PCI? (Select all that apply)', 'The nurse is planning care. Which items apply to "Chest tube handling" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "Avoid kinks in tubing is listed."}, {"id": "b", "text": "Tube removal is based only on patient request."}, {"id": "c", "text": "Dependent tubing is emphasized."}, {"id": "d", "text": "Removal threshold <25–50 mL/shift is listed."}, {"id": "e", "text": "Clamp chest tubes routinely to test patency."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Chest tubes should remain dependent without kinks and may be removed when output drops below 25–50 mL per shift.', 'CABG and PCI - NCLEX', true, 68, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Post-CABG arrhythmia" in CABG & PCI? (Select all that apply)', 'Which of the following are consistent with "Post-CABG arrhythmia" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "Peak timing days 2–4 is listed."}, {"id": "b", "text": "AF is most common post-CABG arrhythmia."}, {"id": "c", "text": "Arrhythmias occur only immediately in OR."}, {"id": "d", "text": "V-fib is listed most common post-CABG rhythm."}, {"id": "e", "text": "Continuous monitoring is needed."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Atrial fibrillation is the most common arrhythmia after CABG, typically on post-op days 2–4.', 'CABG and PCI - NCLEX', true, 69, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Tamponade vigilance" in CABG & PCI? (Select all that apply)', 'During reassessment, which observations align with "Tamponade vigilance" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "Tamponade risk is absent after CABG."}, {"id": "b", "text": "Beck''s triad monitoring is listed post-CABG."}, {"id": "c", "text": "MAP ≥65 target is listed."}, {"id": "d", "text": "Hemodynamic deterioration can indicate tamponade."}, {"id": "e", "text": "MAP target under 40 is acceptable."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Post-CABG priorities include monitoring for tamponade using Beck''s triad and maintaining MAP at least 65.', 'CABG and PCI - NCLEX', true, 70, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Sternal precautions lifting" in CABG & PCI are correct? (Select all that apply)', 'Which statements about "Sternal precautions lifting" in CABG & PCI are correct? (Select all that apply)', '[{"id": "a", "text": "Precaution supports sternal healing."}, {"id": "b", "text": "Heavy lifting accelerates healing."}, {"id": "c", "text": "Lifting limit 5–10 lb is listed."}, {"id": "d", "text": "No lifting restrictions exist post-CABG."}, {"id": "e", "text": "Restriction duration 6–8 weeks is listed."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Sternal precautions include no lifting over 5–10 pounds for 6–8 weeks.', 'CABG and PCI - NCLEX', true, 71, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For CABG & PCI, which findings or actions relate to "Other sternal precautions"? (Select all that apply)', 'For CABG & PCI, which findings or actions relate to "Other sternal precautions"? (Select all that apply)', '[{"id": "a", "text": "No driving 4–6 weeks is listed."}, {"id": "b", "text": "Heavy push/pull restriction is listed."}, {"id": "c", "text": "Unrestricted driving starts day after surgery."}, {"id": "d", "text": "Pillow splinting when coughing is listed."}, {"id": "e", "text": "Coughing should avoid splint support."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: No heavy pushing/pulling, no driving 4–6 weeks, and splint sternum with pillow when coughing/sneezing.', 'CABG and PCI - NCLEX', true, 72, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Sternal wound red flags" in CABG & PCI? (Select all that apply)', 'The nurse is planning care. Which items apply to "Sternal wound red flags" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "Sternal clicking indicates normal healing."}, {"id": "b", "text": "Prompt reporting is part of discharge teaching."}, {"id": "c", "text": "Drainage/fever/redness are warning signs."}, {"id": "d", "text": "Sternal clicking is warning sign."}, {"id": "e", "text": "Redness and fever are expected, no report needed."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Patients should report sternal clicking, drainage, fever, or increasing redness.', 'CABG and PCI - NCLEX', true, 73, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "PCI vs CABG outcomes summary" in CABG & PCI? (Select all that apply)', 'Which of the following are consistent with "PCI vs CABG outcomes summary" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "CABG is first choice for all simple 1-vessel lesions."}, {"id": "b", "text": "Procedure selection differs by disease complexity."}, {"id": "c", "text": "PCI recovery is faster in comparison table."}, {"id": "d", "text": "CABG preferred for left main/3-vessel/DM/low EF patterns."}, {"id": "e", "text": "PCI recovery is listed longer than CABG."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: PCI has shorter recovery and suits selected 1–2 vessel/STEMI/high-surgical-risk cases; CABG has longer recovery and suits left main/multivessel/DM/low EF.', 'CABG and PCI - NCLEX', true, 74, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "NCLEX priority synthesis" in CABG & PCI? (Select all that apply)', 'During reassessment, which observations align with "NCLEX priority synthesis" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "Tamponade surveillance is not needed after CABG."}, {"id": "b", "text": "Tamponade assessment is highlighted NCLEX priority."}, {"id": "c", "text": "Sternal precautions are highlighted NCLEX priority."}, {"id": "d", "text": "DAPT adherence post-PCI is highlighted NCLEX priority."}, {"id": "e", "text": "Medication adherence is optional after stent."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: NCLEX priorities emphasize post-CABG tamponade assessment, strict sternal precautions, and post-PCI DAPT compliance.', 'CABG and PCI - NCLEX', true, 75, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "CAD progression" in CABG & PCI are correct? (Select all that apply)', 'Which statements about "CAD progression" in CABG & PCI are correct? (Select all that apply)', '[{"id": "a", "text": "STEMI is earliest stage."}, {"id": "b", "text": "Progression reflects worsening myocardial perfusion."}, {"id": "c", "text": "CAD progression ends at stable angina."}, {"id": "d", "text": "NSTEMI and STEMI are later stages."}, {"id": "e", "text": "Stable angina appears before unstable in progression."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: CAD progression listed is stable angina to unstable angina to NSTEMI to STEMI.', 'CABG and PCI - NCLEX', true, 76, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For CABG & PCI, which findings or actions relate to "Revascularization options"? (Select all that apply)', 'For CABG & PCI, which findings or actions relate to "Revascularization options"? (Select all that apply)', '[{"id": "a", "text": "EF is irrelevant to decision."}, {"id": "b", "text": "Selection factors include vessels/anatomy/EF/comorbidities."}, {"id": "c", "text": "PCI and CABG are interchangeable regardless anatomy."}, {"id": "d", "text": "PCI is less invasive option."}, {"id": "e", "text": "CABG is surgical option."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Two options are PCI (less invasive) and CABG (surgery), selected by vessel count, anatomy, EF, and comorbidities.', 'CABG and PCI - NCLEX', true, 77, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "PCI basics" in CABG & PCI? (Select all that apply)', 'The nurse is planning care. Which items apply to "PCI basics" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "Stent scaffold may be left in artery."}, {"id": "b", "text": "PCI is open-heart surgery."}, {"id": "c", "text": "Balloon compresses plaque."}, {"id": "d", "text": "Radial and femoral access are listed."}, {"id": "e", "text": "PCI never uses stents."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: PCI is catheter-based via radial or femoral access, using balloon angioplasty and often stent placement.', 'CABG and PCI - NCLEX', true, 78, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Drug-eluting stent role" in CABG & PCI? (Select all that apply)', 'Which of the following are consistent with "Drug-eluting stent role" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "DES aims to lower restenosis risk."}, {"id": "b", "text": "Stent choice affects post-procedure management."}, {"id": "c", "text": "DES has antiproliferative coating."}, {"id": "d", "text": "DES increases restenosis intentionally."}, {"id": "e", "text": "DES removes need for any antiplatelet therapy."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Drug-eluting stents contain antiproliferative medication to reduce restenosis.', 'CABG and PCI - NCLEX', true, 79, 1, true);
