  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Primary PCI timing" in CABG & PCI? (Select all that apply)', 'During reassessment, which observations align with "Primary PCI timing" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "STEMI door-to-balloon target is 90 min."}, {"id": "b", "text": "Rapid activation is essential."}, {"id": "c", "text": "Primary PCI is preferred STEMI reperfusion strategy."}, {"id": "d", "text": "Primary PCI is not used for STEMI."}, {"id": "e", "text": "Primary PCI target is 24 hours."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Primary PCI is treatment of choice for STEMI with door-to-balloon goal within 90 minutes.', 'CABG and PCI - NCLEX', true, 80, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "PCI indications" in CABG & PCI are correct? (Select all that apply)', 'Which statements about "PCI indications" in CABG & PCI are correct? (Select all that apply)', '[{"id": "a", "text": "STEMI and NSTEMI are listed indications."}, {"id": "b", "text": "1–2 vessel suitable anatomy is listed indication."}, {"id": "c", "text": "Refractory unstable angina is listed indication."}, {"id": "d", "text": "Left main multivessel disease is always first-choice PCI."}, {"id": "e", "text": "PCI is contraindicated in all acute MI."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: PCI indications include STEMI/NSTEMI, refractory unstable angina, suitable 1–2 vessel disease, or high CABG surgical risk.', 'CABG and PCI - NCLEX', true, 81, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For CABG & PCI, which findings or actions relate to "Pre-PCI preparation"? (Select all that apply)', 'For CABG & PCI, which findings or actions relate to "Pre-PCI preparation"? (Select all that apply)', '[{"id": "a", "text": "NPO 4–6 hours is listed."}, {"id": "b", "text": "Pedal pulses are assessed/marked pre-procedure."}, {"id": "c", "text": "Pulse baseline is not needed."}, {"id": "d", "text": "Renal function check is unnecessary pre-PCI."}, {"id": "e", "text": "Creatinine check is listed for contrast risk."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Pre-PCI care includes NPO 4–6 hours, IV access, type and screen, DAPT initiation, anticoagulation, creatinine check, and pulse marking.', 'CABG and PCI - NCLEX', true, 82, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Post-PCI vitals and site care" in CABG & PCI? (Select all that apply)', 'The nurse is planning care. Which items apply to "Post-PCI vitals and site care" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "Bleeding/hematoma monitoring is required."}, {"id": "b", "text": "Vitals can be deferred for several hours."}, {"id": "c", "text": "Access-site surveillance is key post-PCI."}, {"id": "d", "text": "Site checks are unnecessary after sheath removal."}, {"id": "e", "text": "Frequent scheduled vitals are listed."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Post-PCI protocol includes frequent vitals and puncture site checks for bleeding/hematoma.', 'CABG and PCI - NCLEX', true, 83, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Post-PCI limb and hydration" in CABG & PCI? (Select all that apply)', 'Which of the following are consistent with "Post-PCI limb and hydration" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "Hydration is encouraged to flush contrast."}, {"id": "b", "text": "Immediate vigorous leg flexion is recommended."}, {"id": "c", "text": "Fluid restriction is mandatory after contrast."}, {"id": "d", "text": "Bedrest 4–6 hours listed for femoral access."}, {"id": "e", "text": "Affected femoral limb kept straight post-procedure."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Femoral approach requires limb straight with bedrest 4–6 hours; fluids are encouraged to clear contrast.', 'CABG and PCI - NCLEX', true, 84, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Post-PCI medication adherence" in CABG & PCI? (Select all that apply)', 'During reassessment, which observations align with "Post-PCI medication adherence" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "DAPT minimum one year is listed."}, {"id": "b", "text": "Aspirin + P2Y12 strategy is emphasized."}, {"id": "c", "text": "DAPT stops after 48 hours."}, {"id": "d", "text": "Aspirin alone is immediate replacement for all stent patients."}, {"id": "e", "text": "Medication adherence is critical after stent."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Dual antiplatelet therapy is required for at least 1 year after stent placement.', 'CABG and PCI - NCLEX', true, 85, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "PCI complications" in CABG & PCI are correct? (Select all that apply)', 'Which statements about "PCI complications" in CABG & PCI are correct? (Select all that apply)', '[{"id": "a", "text": "Bleeding at access site is most common complication listed."}, {"id": "b", "text": "Stent thrombosis is emergency complication."}, {"id": "c", "text": "Restenosis is impossible with stents."}, {"id": "d", "text": "Contrast nephropathy is listed."}, {"id": "e", "text": "PCI has no renal complications."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Listed PCI complications include access-site bleeding (most common), contrast nephropathy, arterial dissection, restenosis/re-occlusion, and stent thrombosis.', 'CABG and PCI - NCLEX', true, 86, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For CABG & PCI, which findings or actions relate to "CABG definition"? (Select all that apply)', 'For CABG & PCI, which findings or actions relate to "CABG definition"? (Select all that apply)', '[{"id": "a", "text": "CABG is open-heart surgery in note."}, {"id": "b", "text": "CABG is a bedside catheter procedure."}, {"id": "c", "text": "CABG is revascularization option for complex CAD."}, {"id": "d", "text": "CABG avoids any graft vessel use."}, {"id": "e", "text": "Bypass grafts reroute flow around blockage."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: CABG is open-heart bypass surgery using grafts to route blood around blocked coronaries.', 'CABG and PCI - NCLEX', true, 87, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "CABG graft options" in CABG & PCI? (Select all that apply)', 'The nurse is planning care. Which items apply to "CABG graft options" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "LIMA-to-LAD is highlighted as durable."}, {"id": "b", "text": "Only synthetic grafts are used."}, {"id": "c", "text": "Radial artery can be used."}, {"id": "d", "text": "Saphenous vein graft is listed."}, {"id": "e", "text": "Internal mammary graft is never connected to LAD."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Graft choices include reversed saphenous vein, internal mammary artery (most durable to LAD), and radial artery.', 'CABG and PCI - NCLEX', true, 88, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "CABG indications high risk anatomy" in CABG & PCI? (Select all that apply)', 'Which of the following are consistent with "CABG indications high risk anatomy" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "Left main >50% is listed indication."}, {"id": "b", "text": "3-vessel with low EF favors CABG."}, {"id": "c", "text": "Proximal LAD involvement in 2-vessel disease listed indication."}, {"id": "d", "text": "Single-vessel mild disease always requires CABG."}, {"id": "e", "text": "Left main stenosis is managed only with lifestyle."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: CABG indications include left main disease >50%, 3-vessel CAD especially with reduced EF, and proximal LAD involvement.', 'CABG and PCI - NCLEX', true, 89, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Other CABG indications" in CABG & PCI? (Select all that apply)', 'During reassessment, which observations align with "Other CABG indications" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "Failed PCI is listed CABG indication."}, {"id": "b", "text": "Diabetes with multivessel CAD is listed indication."}, {"id": "c", "text": "Diabetic multivessel CAD always avoids surgery."}, {"id": "d", "text": "CABG is contraindicated after failed PCI."}, {"id": "e", "text": "CABG can be chosen when PCI strategy insufficient."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: CABG is indicated for failed PCI and in diabetic patients with multivessel CAD.', 'CABG and PCI - NCLEX', true, 90, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Post-CABG airway care" in CABG & PCI are correct? (Select all that apply)', 'Which statements about "Post-CABG airway care" in CABG & PCI are correct? (Select all that apply)', '[{"id": "a", "text": "ABG monitoring is listed."}, {"id": "b", "text": "Incentive spirometry/deep breathing are listed."}, {"id": "c", "text": "Initial intubation then extubation when ready is listed."}, {"id": "d", "text": "ABGs are irrelevant post-CABG."}, {"id": "e", "text": "Pulmonary exercises are avoided after CABG."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Post-op patient is initially intubated, extubated when stable; monitor ABGs and use incentive spirometry/deep breathing to prevent atelectasis.', 'CABG and PCI - NCLEX', true, 91, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For CABG & PCI, which findings or actions relate to "Chest tube threshold"? (Select all that apply)', 'For CABG & PCI, which findings or actions relate to "Chest tube threshold"? (Select all that apply)', '[{"id": "a", "text": "High output indicates possible hemorrhage."}, {"id": "b", "text": "Escalation/notification is required."}, {"id": "c", "text": "Chest tube output trends are unimportant."}, {"id": "d", "text": ">100 mL/hr for 2+ hr threshold is listed."}, {"id": "e", "text": "500 mL/hr output is expected and ignored."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Chest tube output greater than 100 mL/hr for 2+ hours suggests hemorrhage and requires provider notification.', 'CABG and PCI - NCLEX', true, 92, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Chest tube handling" in CABG & PCI? (Select all that apply)', 'The nurse is planning care. Which items apply to "Chest tube handling" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "Removal threshold <25–50 mL/shift is listed."}, {"id": "b", "text": "Dependent tubing is emphasized."}, {"id": "c", "text": "Tube removal is based only on patient request."}, {"id": "d", "text": "Clamp chest tubes routinely to test patency."}, {"id": "e", "text": "Avoid kinks in tubing is listed."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Chest tubes should remain dependent without kinks and may be removed when output drops below 25–50 mL per shift.', 'CABG and PCI - NCLEX', true, 93, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Post-CABG arrhythmia" in CABG & PCI? (Select all that apply)', 'Which of the following are consistent with "Post-CABG arrhythmia" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "Peak timing days 2–4 is listed."}, {"id": "b", "text": "Arrhythmias occur only immediately in OR."}, {"id": "c", "text": "AF is most common post-CABG arrhythmia."}, {"id": "d", "text": "Continuous monitoring is needed."}, {"id": "e", "text": "V-fib is listed most common post-CABG rhythm."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Atrial fibrillation is the most common arrhythmia after CABG, typically on post-op days 2–4.', 'CABG and PCI - NCLEX', true, 94, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Tamponade vigilance" in CABG & PCI? (Select all that apply)', 'During reassessment, which observations align with "Tamponade vigilance" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "Beck''s triad monitoring is listed post-CABG."}, {"id": "b", "text": "Hemodynamic deterioration can indicate tamponade."}, {"id": "c", "text": "MAP target under 40 is acceptable."}, {"id": "d", "text": "Tamponade risk is absent after CABG."}, {"id": "e", "text": "MAP ≥65 target is listed."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Post-CABG priorities include monitoring for tamponade using Beck''s triad and maintaining MAP at least 65.', 'CABG and PCI - NCLEX', true, 95, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Sternal precautions lifting" in CABG & PCI are correct? (Select all that apply)', 'Which statements about "Sternal precautions lifting" in CABG & PCI are correct? (Select all that apply)', '[{"id": "a", "text": "Heavy lifting accelerates healing."}, {"id": "b", "text": "Precaution supports sternal healing."}, {"id": "c", "text": "Lifting limit 5–10 lb is listed."}, {"id": "d", "text": "Restriction duration 6–8 weeks is listed."}, {"id": "e", "text": "No lifting restrictions exist post-CABG."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Sternal precautions include no lifting over 5–10 pounds for 6–8 weeks.', 'CABG and PCI - NCLEX', true, 96, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For CABG & PCI, which findings or actions relate to "Other sternal precautions"? (Select all that apply)', 'For CABG & PCI, which findings or actions relate to "Other sternal precautions"? (Select all that apply)', '[{"id": "a", "text": "Heavy push/pull restriction is listed."}, {"id": "b", "text": "No driving 4–6 weeks is listed."}, {"id": "c", "text": "Coughing should avoid splint support."}, {"id": "d", "text": "Unrestricted driving starts day after surgery."}, {"id": "e", "text": "Pillow splinting when coughing is listed."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: No heavy pushing/pulling, no driving 4–6 weeks, and splint sternum with pillow when coughing/sneezing.', 'CABG and PCI - NCLEX', true, 97, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Sternal wound red flags" in CABG & PCI? (Select all that apply)', 'The nurse is planning care. Which items apply to "Sternal wound red flags" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "Sternal clicking is warning sign."}, {"id": "b", "text": "Redness and fever are expected, no report needed."}, {"id": "c", "text": "Drainage/fever/redness are warning signs."}, {"id": "d", "text": "Prompt reporting is part of discharge teaching."}, {"id": "e", "text": "Sternal clicking indicates normal healing."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Patients should report sternal clicking, drainage, fever, or increasing redness.', 'CABG and PCI - NCLEX', true, 98, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "PCI vs CABG outcomes summary" in CABG & PCI? (Select all that apply)', 'Which of the following are consistent with "PCI vs CABG outcomes summary" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "CABG preferred for left main/3-vessel/DM/low EF patterns."}, {"id": "b", "text": "Procedure selection differs by disease complexity."}, {"id": "c", "text": "PCI recovery is listed longer than CABG."}, {"id": "d", "text": "CABG is first choice for all simple 1-vessel lesions."}, {"id": "e", "text": "PCI recovery is faster in comparison table."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: PCI has shorter recovery and suits selected 1–2 vessel/STEMI/high-surgical-risk cases; CABG has longer recovery and suits left main/multivessel/DM/low EF.', 'CABG and PCI - NCLEX', true, 99, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "NCLEX priority synthesis" in CABG & PCI? (Select all that apply)', 'During reassessment, which observations align with "NCLEX priority synthesis" in CABG & PCI? (Select all that apply)', '[{"id": "a", "text": "DAPT adherence post-PCI is highlighted NCLEX priority."}, {"id": "b", "text": "Tamponade assessment is highlighted NCLEX priority."}, {"id": "c", "text": "Tamponade surveillance is not needed after CABG."}, {"id": "d", "text": "Medication adherence is optional after stent."}, {"id": "e", "text": "Sternal precautions are highlighted NCLEX priority."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: NCLEX priorities emphasize post-CABG tamponade assessment, strict sternal precautions, and post-PCI DAPT compliance.', 'CABG and PCI - NCLEX', true, 100, 1, true);
